  function displayValue(key,value){if(key==='workZoneId')return zoneName(value);if(key==='catalogId')return catalogRow(value).name||value||'—';if(key==='lastTestDate'||key==='nextTestDate')return fmtDate(value);if(key==='status')return STATUS_LABELS[value]||value||'—';if(key==='active')return value===false?'Yo‘q':'Ha';if(key==='testRequired')return value===false?'Sinov muddati belgilanmaydi':'Davriy sinov talab qilinadi';if(key==='intervalUnit')return UNIT_LABELS[value]||value||'—';return value==null||value===''?'—':String(value);}
  function diff(before,after){
    const ignore=new Set(['id','createdAt','createdBy','createdByName','updatedAt','updatedBy','updatedByName','updatedByRole','testHistory']);const keys=new Set([...Object.keys(before||{}),...Object.keys(after||{})]),rows=[];
    keys.forEach(key=>{if(ignore.has(key)||typeof (before||{})[key]==='object'||typeof (after||{})[key]==='object')return;const a=displayValue(key,(before||{})[key]),b=displayValue(key,(after||{})[key]);if(a!==b)rows.push({label:FIELD_LABELS[key]||key,before:a,after:b});});return rows;
  }
